	TGorogoro* self = (TGorogoro*)spine->getBody();

	if (spine->getTime() == 0) {
		self->goToShortestNextGraphNode();
		self->setBckAnm(2);
	}

	if (self->isReachedToGoalXZ()) {
		if (self->jumpToNextGraphNode() >= 0)
			self->flagJump();
		else
